import { useEffect, useState } from 'react';
import { getAdminStats, getAdminCourses, getAdminActivity } from '../../api';
import { MetricCard, Badge, Card, SectionTitle, Spinner, difficultyVariant } from '../../components/UI';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

const GRADE_COLORS = { A: '#1d9e75', B: '#1a7af0', C: '#ef9f27', D: '#e24b4a', F: '#a32d2d' };

export default function AdminDashboard() {
  const [stats,    setStats]    = useState(null);
  const [courses,  setCourses]  = useState([]);
  const [activity, setActivity] = useState([]);
  const [loading,  setLoading]  = useState(true);

  useEffect(() => {
    Promise.all([getAdminStats(), getAdminCourses(), getAdminActivity()])
      .then(([s, c, a]) => {
        setStats(s.data);
        setCourses(c.data);
        setActivity(a.data);
      }).finally(() => setLoading(false));
  }, []);

  if (loading || !stats) return <Spinner />;

  return (
    <div className="p-6 max-w-5xl">
      <div className="mb-6">
        <h1 className="text-xl font-medium text-gray-900">Platform overview</h1>
        <p className="text-sm text-gray-400 mt-0.5">ai_learning_platform · All data live from MySQL</p>
      </div>

      {/* Metrics */}
      <div className="grid grid-cols-3 md:grid-cols-6 gap-3 mb-6">
        <MetricCard label="Students"    value={stats.students} />
        <MetricCard label="Teachers"    value={stats.teachers} />
        <MetricCard label="Courses"     value={stats.courses} />
        <MetricCard label="Enrollments" value={stats.enrollments} />
        <MetricCard label="Submissions" value={stats.submissions} />
        <MetricCard label="Quizzes"     value={stats.quizzes} />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Grade distribution */}
        <Card>
          <SectionTitle>Grade distribution</SectionTitle>
          <ResponsiveContainer width="100%" height={180}>
            <BarChart data={stats.gradeDistribution} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
              <XAxis dataKey="grade" tick={{ fontSize: 12 }} tickLine={false} axisLine={false} />
              <YAxis tick={{ fontSize: 11 }} tickLine={false} axisLine={false} allowDecimals={false} />
              <Tooltip
                contentStyle={{ fontSize: 12, borderRadius: 8, border: '0.5px solid #eee' }}
                formatter={(v) => [v, 'Students']}
              />
              <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                {stats.gradeDistribution.map((entry) => (
                  <Cell key={entry.grade} fill={GRADE_COLORS[entry.grade] || '#888'} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </Card>

        {/* Activity feed */}
        <Card>
          <SectionTitle>Recent activity</SectionTitle>
          <div className="flex flex-col divide-y divide-gray-50">
            {activity.length === 0 ? (
              <p className="text-sm text-gray-400">No recent activity.</p>
            ) : activity.map((a, i) => (
              <div key={i} className="flex items-start gap-3 py-2.5 first:pt-0 last:pb-0">
                <div className={`w-2 h-2 rounded-full mt-1.5 shrink-0 ${
                  a.type === 'submission' ? 'bg-brand-600' : 'bg-teal-400'
                }`} />
                <div className="min-w-0">
                  <p className="text-sm text-gray-700 truncate">{a.message}</p>
                  <p className="text-xs text-gray-400">
                    {new Date(a.timestamp).toLocaleDateString()}
                  </p>
                </div>
                {a.status && (
                  <Badge
                    label={a.status}
                    variant={a.status === 'Active' || a.status === 'Submitted' ? 'green'
                           : a.status === 'Late' ? 'red' : 'gray'}
                  />
                )}
              </div>
            ))}
          </div>
        </Card>

        {/* Courses table */}
        <Card className="lg:col-span-2">
          <SectionTitle>All courses</SectionTitle>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-xs text-gray-400 border-b border-gray-100">
                  <th className="text-left pb-2 font-medium">Code</th>
                  <th className="text-left pb-2 font-medium">Course</th>
                  <th className="text-left pb-2 font-medium">Teacher</th>
                  <th className="text-left pb-2 font-medium">Level</th>
                  <th className="text-left pb-2 font-medium">Students</th>
                  <th className="text-left pb-2 font-medium">Weeks</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {courses.map(c => (
                  <tr key={c.course_id}>
                    <td className="py-2.5 font-mono text-xs text-brand-600">{c.course_code}</td>
                    <td className="py-2.5 text-gray-800">{c.course_name}</td>
                    <td className="py-2.5 text-gray-500 text-xs">{c.teacher_name}</td>
                    <td className="py-2.5">
                      <Badge label={c.difficulty_level} variant={difficultyVariant(c.difficulty_level)} />
                    </td>
                    <td className="py-2.5 text-gray-600">{c.enrolled_students}</td>
                    <td className="py-2.5 text-gray-400">{c.duration_weeks}w</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Card>
      </div>
    </div>
  );
}
